changeSet.sql:
-- Cave level (id = 1) — bundle entry-point + any referenced textures INSERT INTO level_assets (level_id, label, asset_type, file_path, content_type, uploaded_at) SELECT 1, 'bundle-entry', 'wasm-entry', '/api/assets/levels/cave/index.html', 'text/html', NOW() WHERE NOT EXISTS (SELECT 1 FROM level_assets WHERE level_id = 1 AND label = 'bundle-entry');
-- Field level (id = 2) INSERT INTO level_assets (level_id, label, asset_type, file_path, content_type, uploaded_at) SELECT 2, 'bundle-entry', 'wasm-entry', '/api/assets/levels/field/index.html', 'text/html', NOW() WHERE NOT EXISTS (SELECT 1 FROM level_assets WHERE level_id = 2 AND label = 'bundle-entry');
-- Field textures referenced from scene_elements.textureUrl INSERT INTO level_assets (level_id, label, asset_type, file_path, content_type, uploaded_at) SELECT 2, 'oak-bark', 'texture', '/api/assets/games/field/oak.png', 'image/png', NOW() WHERE NOT EXISTS (SELECT 1 FROM level_assets WHERE level_id = 2 AND label = 'oak-bark');
INSERT INTO level_assets (level_id, label, asset_type, file_path, content_type, uploaded_at) SELECT 2, 'cottage-wall', 'texture', '/api/assets/games/field/cottage.png', 'image/png', NOW() WHERE NOT EXISTS (SELECT 1 FROM level_assets WHERE level_id = 2 AND label = 'cottage-wall');
